#!/usr/bin/env python3
"""
Analytics Reporter — Performance analytics and reporting engine.

Generates performance reports using validated X data. Computes metrics,
compares against benchmarks, identifies top/bottom performers, and
produces structured reports for weekly and monthly reviews.

Designed to be called by an AI agent as part of the review cycle.

Usage:
    from analytics_reporter import AnalyticsReporter

    reporter = AnalyticsReporter(goals_path="config/goals.json")
    report = reporter.generate_report(validated_tweets)
"""

import json
import os
from datetime import datetime
from typing import Dict, List, Optional, Tuple


ENGAGEMENT_BENCHMARKS = {
    "early": {"good": 2.0, "great": 5.0, "exceptional": 10.0},
    "growth": {"good": 1.0, "great": 2.5, "exceptional": 5.0},
    "established": {"good": 0.5, "great": 1.5, "exceptional": 3.0},
    "authority": {"good": 0.3, "great": 1.0, "exceptional": 2.0},
}

IMPRESSIONS_BENCHMARKS = {
    "early": {"low": 50, "average": 200, "high": 1000},
    "growth": {"low": 500, "average": 2000, "high": 20000},
    "established": {"low": 2000, "average": 10000, "high": 100000},
    "authority": {"low": 5000, "average": 20000, "high": 200000},
}


class AnalyticsReporter:
    """Generates performance reports from validated X data."""

    def __init__(self, goals_path: str = "config/goals.json"):
        self.goals = self._load_json(goals_path, {})
        self.growth_stage = self.goals.get("growth_stage", "early")

    def _load_json(self, path: str, default: Dict) -> Dict:
        if os.path.exists(path):
            with open(path, "r") as f:
                return json.load(f)
        return default

    def generate_report(
        self,
        validated_tweets: List[Dict],
        period_label: str = "Report Period",
        previous_period_metrics: Optional[Dict] = None,
    ) -> Dict:
        """
        Generate a comprehensive performance report.

        Args:
            validated_tweets: List of validated tweet objects with metrics.
            period_label: Human-readable label for the report period.
            previous_period_metrics: Previous period summary for comparison.

        Returns:
            Structured performance report.
        """
        if not validated_tweets:
            return {
                "period": period_label,
                "generated_at": datetime.now().isoformat(),
                "status": "NO_DATA",
                "message": "No validated tweets to analyze",
            }

        metrics = self._compute_metrics(validated_tweets)
        top_performers = self._find_top_performers(validated_tweets, n=3)
        bottom_performers = self._find_bottom_performers(validated_tweets, n=3)
        content_breakdown = self._analyze_content_types(validated_tweets)
        timing_analysis = self._analyze_posting_times(validated_tweets)
        benchmark_comparison = self._compare_benchmarks(metrics)

        report = {
            "period": period_label,
            "generated_at": datetime.now().isoformat(),
            "growth_stage": self.growth_stage,
            "summary": metrics,
            "benchmark_comparison": benchmark_comparison,
            "top_performers": top_performers,
            "bottom_performers": bottom_performers,
            "content_type_breakdown": content_breakdown,
            "timing_analysis": timing_analysis,
            "recommendations": self._generate_recommendations(
                metrics, top_performers, bottom_performers, content_breakdown
            ),
        }

        if previous_period_metrics:
            report["period_comparison"] = self._compare_periods(metrics, previous_period_metrics)

        goal_targets = self.goals.get("targets", {}).get("1_month", {})
        if goal_targets:
            report["goal_progress"] = self._assess_goal_progress(metrics, goal_targets)

        return report

    def _compute_metrics(self, tweets: List[Dict]) -> Dict:
        total_impressions = 0
        total_likes = 0
        total_retweets = 0
        total_replies = 0
        total_quotes = 0
        total_bookmarks = 0
        complete_count = 0

        for tweet in tweets:
            m = tweet.get("metrics", {})
            impressions = m.get("impressionCount")
            if impressions is None:
                continue

            complete_count += 1
            total_impressions += impressions
            total_likes += m.get("likeCount") or 0
            total_retweets += m.get("retweetCount") or 0
            total_replies += m.get("replyCount") or 0
            total_quotes += m.get("quoteCount") or 0
            total_bookmarks += m.get("bookmarkCount") or 0

        total_engagement = total_likes + total_retweets + total_replies + total_quotes

        return {
            "total_tweets": len(tweets),
            "tweets_with_complete_data": complete_count,
            "total_impressions": total_impressions,
            "total_engagement": total_engagement,
            "avg_impressions_per_tweet": (
                round(total_impressions / complete_count, 1) if complete_count else None
            ),
            "avg_engagement_per_tweet": (
                round(total_engagement / complete_count, 2) if complete_count else None
            ),
            "engagement_rate_pct": (
                round(total_engagement / total_impressions * 100, 2)
                if total_impressions > 0 else None
            ),
            "engagement_breakdown": {
                "likes": total_likes,
                "retweets": total_retweets,
                "replies": total_replies,
                "quotes": total_quotes,
                "bookmarks": total_bookmarks,
            },
            "engagement_quality": {
                "reply_ratio": (
                    round(total_replies / total_engagement * 100, 1)
                    if total_engagement > 0 else None
                ),
                "bookmark_ratio": (
                    round(total_bookmarks / total_engagement * 100, 1)
                    if total_engagement > 0 else None
                ),
                "note": "Higher reply and bookmark ratios indicate deeper engagement",
            },
        }

    def _find_top_performers(self, tweets: List[Dict], n: int = 3) -> List[Dict]:
        scored = []
        for tweet in tweets:
            m = tweet.get("metrics", {})
            impressions = m.get("impressionCount")
            if not impressions:
                continue
            engagement = sum(
                m.get(k, 0) or 0
                for k in ["likeCount", "retweetCount", "replyCount", "quoteCount"]
            )
            er = engagement / impressions * 100 if impressions > 0 else 0
            scored.append({
                "id": tweet.get("id"),
                "text_preview": tweet.get("text", "")[:120],
                "impressions": impressions,
                "engagement": engagement,
                "engagement_rate_pct": round(er, 2),
                "likes": m.get("likeCount", 0),
                "replies": m.get("replyCount", 0),
                "bookmarks": m.get("bookmarkCount", 0),
                "created_at": tweet.get("createdAt"),
            })

        scored.sort(key=lambda x: x["engagement_rate_pct"], reverse=True)
        return scored[:n]

    def _find_bottom_performers(self, tweets: List[Dict], n: int = 3) -> List[Dict]:
        scored = []
        for tweet in tweets:
            m = tweet.get("metrics", {})
            impressions = m.get("impressionCount")
            if not impressions:
                continue
            engagement = sum(
                m.get(k, 0) or 0
                for k in ["likeCount", "retweetCount", "replyCount", "quoteCount"]
            )
            er = engagement / impressions * 100 if impressions > 0 else 0
            scored.append({
                "id": tweet.get("id"),
                "text_preview": tweet.get("text", "")[:120],
                "impressions": impressions,
                "engagement": engagement,
                "engagement_rate_pct": round(er, 2),
                "created_at": tweet.get("createdAt"),
            })

        scored.sort(key=lambda x: x["engagement_rate_pct"])
        return scored[:n]

    def _analyze_content_types(self, tweets: List[Dict]) -> Dict:
        """Analyze performance by content type (requires type tagging in tweet data)."""
        return {
            "note": "Content type analysis requires tweets to be tagged with pillar types during posting. "
                    "Use the daily review template to track content types manually until automated tagging is available.",
            "total_tweets": len(tweets),
        }

    def _analyze_posting_times(self, tweets: List[Dict]) -> Dict:
        """Analyze performance by posting time."""
        hour_buckets: Dict[int, List[Dict]] = {}

        for tweet in tweets:
            created_at = tweet.get("createdAt")
            if not created_at:
                continue
            try:
                dt = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                hour = dt.hour
            except (ValueError, AttributeError):
                continue

            if hour not in hour_buckets:
                hour_buckets[hour] = []

            m = tweet.get("metrics", {})
            impressions = m.get("impressionCount", 0) or 0
            engagement = sum(
                m.get(k, 0) or 0
                for k in ["likeCount", "retweetCount", "replyCount", "quoteCount"]
            )
            hour_buckets[hour].append({"impressions": impressions, "engagement": engagement})

        time_performance = {}
        for hour, posts in sorted(hour_buckets.items()):
            avg_imp = sum(p["impressions"] for p in posts) / len(posts) if posts else 0
            avg_eng = sum(p["engagement"] for p in posts) / len(posts) if posts else 0
            time_performance[f"{hour:02d}:00 UTC"] = {
                "post_count": len(posts),
                "avg_impressions": round(avg_imp, 1),
                "avg_engagement": round(avg_eng, 2),
            }

        return {
            "by_hour_utc": time_performance,
            "note": "Times are in UTC. Convert to your audience's timezone for actionable insights.",
        }

    def _compare_benchmarks(self, metrics: Dict) -> Dict:
        er = metrics.get("engagement_rate_pct")
        avg_imp = metrics.get("avg_impressions_per_tweet")

        er_bench = ENGAGEMENT_BENCHMARKS.get(self.growth_stage, ENGAGEMENT_BENCHMARKS["early"])
        imp_bench = IMPRESSIONS_BENCHMARKS.get(self.growth_stage, IMPRESSIONS_BENCHMARKS["early"])

        er_rating = "N/A"
        if er is not None:
            if er >= er_bench["exceptional"]:
                er_rating = "EXCEPTIONAL"
            elif er >= er_bench["great"]:
                er_rating = "GREAT"
            elif er >= er_bench["good"]:
                er_rating = "GOOD"
            else:
                er_rating = "BELOW_BENCHMARK"

        imp_rating = "N/A"
        if avg_imp is not None:
            if avg_imp >= imp_bench["high"]:
                imp_rating = "HIGH"
            elif avg_imp >= imp_bench["average"]:
                imp_rating = "AVERAGE"
            elif avg_imp >= imp_bench["low"]:
                imp_rating = "LOW"
            else:
                imp_rating = "BELOW_BENCHMARK"

        return {
            "growth_stage": self.growth_stage,
            "engagement_rate": {
                "actual": er,
                "benchmarks": er_bench,
                "rating": er_rating,
            },
            "impressions": {
                "actual": avg_imp,
                "benchmarks": imp_bench,
                "rating": imp_rating,
            },
        }

    def _compare_periods(self, current: Dict, previous: Dict) -> Dict:
        def pct_change(curr, prev):
            if prev and prev > 0 and curr is not None:
                return round((curr - prev) / prev * 100, 1)
            return None

        return {
            "impressions_change_pct": pct_change(
                current.get("total_impressions"), previous.get("total_impressions")
            ),
            "engagement_rate_change": (
                round(
                    (current.get("engagement_rate_pct") or 0) - (previous.get("engagement_rate_pct") or 0),
                    2,
                )
            ),
            "avg_impressions_change_pct": pct_change(
                current.get("avg_impressions_per_tweet"), previous.get("avg_impressions_per_tweet")
            ),
        }

    def _assess_goal_progress(self, metrics: Dict, targets: Dict) -> Dict:
        progress = {}

        er = metrics.get("engagement_rate_pct")
        er_target = targets.get("avg_engagement_rate_pct")
        if er is not None and er_target:
            progress["engagement_rate"] = {
                "actual": er,
                "target": er_target,
                "status": "ON_TRACK" if er >= er_target else "BEHIND",
            }

        avg_imp = metrics.get("avg_impressions_per_tweet")
        imp_target = targets.get("avg_impressions_per_tweet")
        if avg_imp is not None and imp_target:
            progress["avg_impressions"] = {
                "actual": avg_imp,
                "target": imp_target,
                "status": "ON_TRACK" if avg_imp >= imp_target else "BEHIND",
            }

        return progress

    def _generate_recommendations(
        self,
        metrics: Dict,
        top_performers: List[Dict],
        bottom_performers: List[Dict],
        content_breakdown: Dict,
    ) -> List[str]:
        recs = []

        er = metrics.get("engagement_rate_pct")
        if er is not None and er < 1.0:
            recs.append(
                "Engagement rate is below 1%. Focus on content that generates replies "
                "(questions, contrarian takes) rather than passive likes."
            )

        reply_ratio = metrics.get("engagement_quality", {}).get("reply_ratio")
        if reply_ratio is not None and reply_ratio < 20:
            recs.append(
                "Reply ratio is low. Add discussion prompts and open-ended questions "
                "to your posts. Replies have the highest algorithm weight."
            )

        if top_performers:
            best = top_performers[0]
            recs.append(
                f"Your top performer had {best['engagement_rate_pct']}% ER. "
                f"Analyze what made it work and create similar content."
            )

        if bottom_performers:
            worst = bottom_performers[0]
            if worst["engagement_rate_pct"] == 0:
                recs.append(
                    "You have posts with 0% engagement. Review posting time and content quality. "
                    "Consider if the topic matched your audience's interests."
                )

        return recs


if __name__ == "__main__":
    reporter = AnalyticsReporter()
    print("Analytics Reporter v1.0")
    print("=" * 40)
    print()
    print("This module generates performance reports from validated X data.")
    print("It is designed to be called by an AI agent during review cycles.")
    print()
    print("Usage:")
    print("  from analytics_reporter import AnalyticsReporter")
    print()
    print("  reporter = AnalyticsReporter(goals_path='config/goals.json')")
    print("  report = reporter.generate_report(validated_tweets)")
    print()
    print("See SKILL.md for full integration details.")

#!/usr/bin/env python3
"""
Content Planner — Daily content recommendation engine.

Reads profile, goals, and content calendar configuration to generate
daily content recommendations with content mix compliance tracking.

Designed to be called by an AI agent as part of the daily PDCA loop.

Usage:
    from content_planner import ContentPlanner

    planner = ContentPlanner(
        profile_path="config/profile.json",
        goals_path="config/goals.json",
        calendar_path="config/content-calendar.json"
    )
    recommendation = planner.generate_daily_plan(day_of_week="tuesday")
"""

import json
import os
from datetime import datetime, timedelta
from typing import Dict, List, Optional


CONTENT_PILLARS = {
    "value": {
        "label": "Technical Depth / Value",
        "description": "Tips, insights, tutorials, how-tos",
        "default_target_pct": 40,
        "formats": ["technical insight", "tutorial", "tool comparison", "code snippet"],
    },
    "opinion": {
        "label": "Industry Pulse / Opinion",
        "description": "Contrarian takes, hot takes, predictions, trend analysis",
        "default_target_pct": 25,
        "formats": ["contrarian take", "prediction", "rapid reaction", "industry analysis"],
    },
    "story": {
        "label": "Builder's Journey / Story",
        "description": "Build-in-public, decisions, lessons, failures",
        "default_target_pct": 25,
        "formats": ["build update", "lesson learned", "decision story", "milestone"],
    },
    "engagement": {
        "label": "Community Value / Engagement",
        "description": "Questions, polls, resource shares, community highlights",
        "default_target_pct": 10,
        "formats": ["question", "poll", "resource list", "community highlight"],
    },
}

CONTENT_FORMULAS = [
    {
        "name": "Claim + Evidence + CTA",
        "template": "[Bold claim] → [Evidence/example] → [Discussion prompt]",
        "best_for": ["value", "opinion"],
    },
    {
        "name": "Story + Lesson + Takeaway",
        "template": "[Brief narrative] → [What happened] → [Actionable insight]",
        "best_for": ["story"],
    },
    {
        "name": "Question + Context + Invitation",
        "template": "[Thoughtful question] → [Why asking] → [Invite perspectives]",
        "best_for": ["engagement"],
    },
    {
        "name": "List + Value + CTA",
        "template": "[N items] → [Brief explanation each] → [Bookmark/follow prompt]",
        "best_for": ["value", "engagement"],
    },
    {
        "name": "Reaction + Analysis + Prediction",
        "template": "[News reference] → [Your analysis] → [What happens next]",
        "best_for": ["opinion"],
    },
]

WEEKLY_THEMES = {
    "monday": "Industry Pulse",
    "tuesday": "Technical Depth",
    "wednesday": "Builder's Journey",
    "thursday": "Community Value",
    "friday": "Personal Touch + Recap",
    "saturday": "Light Engagement",
    "sunday": "Review + Planning",
}

PRODUCT_INTEGRATION_TIERS = {
    1: {"label": "Background Presence", "description": "Bio/profile does the work, no explicit mention"},
    2: {"label": "Contextual Reference", "description": "Product as example within broader insight"},
    3: {"label": "Direct Promotion", "description": "Product is the subject: launch, milestone, demo"},
}


class ContentPlanner:
    """Generates daily content recommendations based on configuration and history."""

    def __init__(
        self,
        profile_path: str = "config/profile.json",
        goals_path: str = "config/goals.json",
        calendar_path: str = "config/content-calendar.json",
    ):
        self.profile = self._load_json(profile_path, {})
        self.goals = self._load_json(goals_path, {})
        self.calendar = self._load_json(calendar_path, {})
        self.content_mix_targets = self._get_content_mix_targets()

    def _load_json(self, path: str, default: Dict) -> Dict:
        if os.path.exists(path):
            with open(path, "r") as f:
                return json.load(f)
        return default

    def _get_content_mix_targets(self) -> Dict[str, int]:
        mix = self.goals.get("content_mix", {})
        return {
            "value": mix.get("value_tweets_pct", 40),
            "opinion": mix.get("opinion_tweets_pct", 25),
            "story": mix.get("story_tweets_pct", 25),
            "engagement": mix.get("engagement_tweets_pct", 10),
        }

    def generate_daily_plan(
        self,
        day_of_week: Optional[str] = None,
        week_history: Optional[Dict[str, int]] = None,
        trending_topics: Optional[List[str]] = None,
    ) -> Dict:
        """
        Generate content recommendations for today.

        Args:
            day_of_week: e.g. "tuesday". Auto-detected if None.
            week_history: Content pillar counts so far this week,
                          e.g. {"value": 5, "opinion": 3, "story": 2, "engagement": 1}
            trending_topics: Current trending topics to potentially react to.

        Returns:
            Daily content plan with recommendations.
        """
        if day_of_week is None:
            day_of_week = datetime.now().strftime("%A").lower()

        theme = WEEKLY_THEMES.get(day_of_week, "General")
        compliance = self._check_mix_compliance(week_history or {})
        is_thread_day = self._is_thread_day(day_of_week)

        recommendations = []

        priority_pillar = compliance.get("most_underrepresented")
        if priority_pillar:
            rec = self._generate_recommendation(
                pillar=priority_pillar,
                reason=f"Underrepresented this week ({compliance['actual'].get(priority_pillar, 0)}% vs {self.content_mix_targets.get(priority_pillar, 0)}% target)",
                trending_topics=trending_topics,
            )
            recommendations.append(rec)

        theme_pillar = self._theme_to_pillar(theme)
        if theme_pillar and theme_pillar != priority_pillar:
            rec = self._generate_recommendation(
                pillar=theme_pillar,
                reason=f"Today's theme: {theme}",
                trending_topics=trending_topics,
            )
            recommendations.append(rec)

        if len(recommendations) < 2:
            filler_pillar = "value" if "value" not in [r["pillar"] for r in recommendations] else "opinion"
            rec = self._generate_recommendation(
                pillar=filler_pillar,
                reason="Fill daily post quota",
                trending_topics=trending_topics,
            )
            recommendations.append(rec)

        for i, rec in enumerate(recommendations):
            rec["product_integration"] = self._suggest_integration_tier(i, len(recommendations))

        plan = {
            "date": datetime.now().strftime("%Y-%m-%d"),
            "day_of_week": day_of_week,
            "theme": theme,
            "is_thread_day": is_thread_day,
            "content_mix_compliance": compliance,
            "recommendations": recommendations,
            "engagement_targets": self._get_engagement_targets(),
        }

        if is_thread_day:
            plan["thread_note"] = (
                "Thread day! Post your prepared thread during Window A "
                "(08:00-10:00 in target audience timezone). "
                "Include visuals in 60-70% of thread tweets."
            )

        if trending_topics:
            plan["trending_topics"] = trending_topics
            plan["trending_note"] = (
                "Consider a rapid-reaction tweet to a trending topic. "
                "Post within 2 hours of breaking for maximum algorithmic boost."
            )

        return plan

    def _check_mix_compliance(self, week_history: Dict[str, int]) -> Dict:
        total = sum(week_history.values()) or 1
        actual = {k: round(week_history.get(k, 0) / total * 100, 1) for k in self.content_mix_targets}

        deviations = {}
        for pillar, target in self.content_mix_targets.items():
            deviations[pillar] = actual.get(pillar, 0) - target

        most_under = min(deviations, key=deviations.get) if deviations else None

        return {
            "actual": actual,
            "target": self.content_mix_targets,
            "deviations": deviations,
            "most_underrepresented": most_under if deviations.get(most_under, 0) < -5 else None,
            "status": "ON_TRACK" if all(abs(v) <= 10 for v in deviations.values()) else "NEEDS_ADJUSTMENT",
        }

    def _generate_recommendation(
        self,
        pillar: str,
        reason: str,
        trending_topics: Optional[List[str]] = None,
    ) -> Dict:
        pillar_info = CONTENT_PILLARS.get(pillar, CONTENT_PILLARS["value"])
        matching_formulas = [f for f in CONTENT_FORMULAS if pillar in f["best_for"]]

        rec = {
            "pillar": pillar,
            "pillar_label": pillar_info["label"],
            "reason": reason,
            "suggested_formats": pillar_info["formats"],
            "suggested_formula": matching_formulas[0]["name"] if matching_formulas else None,
            "formula_template": matching_formulas[0]["template"] if matching_formulas else None,
            "multimodal_suggestion": self._suggest_visual(pillar),
        }

        if trending_topics and pillar in ("opinion", "value"):
            rec["trending_angle"] = (
                f"Consider reacting to: {trending_topics[0]}"
                if trending_topics else None
            )

        return rec

    def _suggest_visual(self, pillar: str) -> str:
        visual_map = {
            "value": "Code screenshot, diagram, or terminal output",
            "opinion": "Data visualization or comparison diagram",
            "story": "Dashboard screenshot, product screenshot, or workspace photo",
            "engagement": "Poll (built-in X feature) or comparison table image",
        }
        return visual_map.get(pillar, "Consider adding a relevant image")

    def _suggest_integration_tier(self, index: int, total: int) -> Dict:
        if index == 0:
            return PRODUCT_INTEGRATION_TIERS[1]
        elif index == total - 1 and total > 2:
            return PRODUCT_INTEGRATION_TIERS[2]
        return PRODUCT_INTEGRATION_TIERS[1]

    def _is_thread_day(self, day_of_week: str) -> bool:
        cal_day = self.calendar.get("weekly_rhythm", {}).get(day_of_week, {})
        return cal_day.get("thread_day", day_of_week in ("tuesday", "thursday"))

    def _theme_to_pillar(self, theme: str) -> Optional[str]:
        mapping = {
            "Industry Pulse": "opinion",
            "Technical Depth": "value",
            "Builder's Journey": "story",
            "Community Value": "engagement",
            "Personal Touch + Recap": "story",
            "Light Engagement": "engagement",
        }
        return mapping.get(theme)

    def _get_engagement_targets(self) -> Dict:
        targets = self.goals.get("targets", {}).get("1_month", {})
        return {
            "daily_replies_target": targets.get("daily_replies", 10),
            "core_circle_engagement": "Reply to 10-15 accounts before posting",
            "reply_quality_minimum": "Level C (thoughtful question) or above",
            "community_posting": "Post in 1-2 X Communities if relevant",
        }


